      $('planning-intake-apply').disabled=stale;$('planning-intake-recheck').hidden=!stale;
      status('planning-intake-review-status',stale?'查看条件后，当前表单已有编辑或草稿更换。请先重新核对，再决定是否另建空白计划。':'还未写入任何表单。逐项核对下方条件与原话，确认后才会采用。');
