      const linked=data.budget.options.filter(o=>o.goals.includes(g.id));host.append(node('p','逐一核对：现状是否仍已达成；以下项目是否真的达到新目标，以及它们的效果依据。已完成的旧项目若达不到新目标，请取消它与这个目标的关联，不要取消真实完成历史。','muted'));const list=node('ul');for(const o of linked)list.append(node('li',(o.label||o.id)+(o.completed?'（已经完成）':'（尚未完成）')));if(!linked.length)list.append(node('li','目前没有候选关联此目标'));host.append(list);
